update public.shop_sources set crawled = coalesce(crawled, '{}'::jsonb) || $j${"address": "50 Tôn Thất Tùng, Phường Phạm Ngũ Lão, Quận 1, TP.HCM", "phone": "+84 96 868 1111", "menu": [{"name": "Dental implant (all-inclusive)", "name_ko": "치과 임플란트 (모두 포함)", "minutes": null, "price": "từ $399", "section": "Dental", "section_ko": "치과", "desc_ko": "임플란트 · 모든 비용 포함 (홈페이지 기준 시작가)", "desc": "Implant, all-inclusive (starting price)"}], "features": ["24시간 상담", "공항 픽업", "수술 후 관리", "성형 · 치과 · 피부과 함께 운영"], "deals": ["한국식 성형 최대 50% 할인 (홈페이지 광고 · 조건 확인 필요)"], "about": {"facts": ["베트남 보건부 허가 종합 병원 (성형 · 치과 · 피부과)", "마취과 전문의 상주", "외국인 환자 공항 픽업 · 수술 후 관리"], "desc_ko": "호치민 1군에 있는 한국식 성형 병원이에요. 성형외과 · 치과 · 피부과를 함께 보고, 마취과 의사가 상주해요. 외국인 환자는 공항 픽업과 수술 후 관리를 받을 수 있어요.", "desc_en": "A Korean-style cosmetic hospital in District 1 covering plastic surgery, dentistry and dermatology, with an anesthesiologist on staff. International patients get airport pickup and post-op care.", "desc_vi": "Bệnh viện thẩm mỹ theo chuẩn Hàn Quốc ở Quận 1, gồm phẫu thuật thẩm mỹ, nha khoa và da liễu, có bác sĩ gây mê thường trực. Bệnh nhân quốc tế được đón sân bay và chăm sóc hậu phẫu.", "reco_ko": "성형과 치과를 한곳에서 상담받고 싶은 분", "reco_en": "Those who want surgery and dental consults in one place", "reco_vi": "Người muốn tư vấn thẩm mỹ và nha khoa cùng nơi"}, "note": "성형 가격은 홈페이지에 없어요 (상담)", "src": ["https://jwhospital.vn/"]}$j$::jsonb, crawled_at = now() where shop_id = 'jw-korea-hospital' and coalesce(review, '') <> 'done';

