update public.shop_sources set crawled = coalesce(crawled, '{}'::jsonb) || $j${"address": "266 Trần Phú, Phước Ninh, Hải Châu, Đà Nẵng", "phone": "0909 433 086", "deals": ["온라인 예약 최대 30% 할인 (60분 전 예약 · 홈페이지 가격은 정가)"], "about": {"facts": ["다낭 본점 · 달랏 · 나트랑 · 후에 지점", "천연 원료 스파 제품 사용", "핫스톤 · 타이 · 임산부 · 발 · 얼굴 관리"], "desc_ko": "다낭 쩐푸 거리에 본점이 있는 스파예요. 달랏 · 나트랑 · 후에에도 지점이 있고, 핫스톤 · 타이 · 임산부 마사지와 얼굴 관리를 해요. 홈페이지로 미리 예약하면 할인이 있어요.", "desc_en": "A spa headquartered on Tran Phu Street in Da Nang, with branches in Da Lat, Nha Trang and Hue. It offers hot stone, Thai and prenatal massage plus facials, with a discount for booking online in advance.", "desc_vi": "Spa có trụ sở trên đường Trần Phú, Đà Nẵng, chi nhánh ở Đà Lạt, Nha Trang, Huế. Có massage đá nóng, Thái, bầu và chăm sóc da mặt; đặt trước online được giảm giá.", "reco_ko": "시내 중심에서 조용한 개인실을 원하는 분", "reco_en": "Those who want a quiet private room downtown", "reco_vi": "Người muốn phòng riêng yên tĩnh ở trung tâm"}, "note": "가격표가 그림이에요 → 업체 검수에서 📋 캡처 붙여넣기로 가져오면 돼요 (https://cloverspa.vn/en/price-list.html)", "src": ["https://cloverspa.vn/en/price-list.html"]}$j$::jsonb, crawled_at = now() where shop_id = 'clover-spa' and coalesce(review, '') <> 'done';

