update public.shop_sources set crawled = coalesce(crawled, '{}'::jsonb) || $j${"address": "250 Dã Tượng, Vĩnh Nguyên, Nha Trang", "phone": "079 77 68 999 (Viber · Zalo) · 0258 3887 798", "note": "⚠️ 반영구(phun xăm)도 해요 — 엉클데이에서는 빼야 해요 · 가격표가 그림 12장이에요 → 📋 캡처 붙여넣기로 가져오면 돼요 (https://seraspa.com.vn/bang-gia-dich-vu)", "src": ["https://seraspa.com.vn/bang-gia-dich-vu", "https://seraspa.com.vn/"], "hours": "08:00 - 20:00 (매일)", "about": {"facts": ["나트랑 다뜨엉 거리", "얼굴 · 바디 · 발 관리와 여드름 치료", "보톡스 · 필러 등 시술도 함께"], "desc_ko": "나트랑에 있는 스파 겸 미용 클리닉이에요. 얼굴 · 바디 · 발 관리와 여드름 치료를 하고, 매일 아침 8시부터 저녁 8시까지 열어요.", "desc_en": "A spa and beauty clinic in Nha Trang offering facials, body and foot care and acne treatment, open daily from 8 AM to 8 PM.", "desc_vi": "Spa kiêm phòng khám thẩm mỹ ở Nha Trang: chăm sóc da mặt, body, chân và điều trị mụn; mở cửa hằng ngày 8:00–20:00.", "reco_ko": "여드름 · 피부 고민을 관리받고 싶은 분", "reco_en": "Those with acne or skin concerns", "reco_vi": "Người có vấn đề về mụn, da"}}$j$::jsonb, crawled_at = now() where shop_id = 'seras-spa' and coalesce(review, '') <> 'done';

select shop_id, review as "검수", jsonb_array_length(coalesce(crawled -> 'menu', '[]'::jsonb)) as "메뉴 줄", crawled ->> 'note' as "확인 메모" from public.shop_sources where shop_id in ('herbal-spa', 'ngo-massage-spa', 'swan-spa', 'golden-lotus-spa', 'la-maison-grand-spa', 'la-belle-spa', 'dr-harvard', 'linh-chau', 'jw-korea-hospital', 'dr-quang-tuan', 'villa-aesthetica', 'dong-a-beauty', 'clover-spa', 'seras-spa') order by shop_id;
